/**
 * HURFORD'S QLD SOLID FLOORING — generated, do not hand-edit.
 *
 * Source: Hurford's QLD Solid Flooring Products Price List, effective 12 February 2026
 * Regenerate: python3 scripts/extract-hurfords-solid.py
 *
 * 552 product rows across 8 ranges, from 553 source rows less the one
 * captured sub-heading. All rates ex GST. Hurford's THIRD list, after the plywood
 * and the engineered flooring.
 *
 * THE GRADE IS PUNCHED OUT OF THE PRODUCT CODE. 529 codes print '##' or a single
 * '#' where the two-letter grade code belongs. Substituting the row's own grade
 * code resolves all 552 with no collisions. `code` is orderable, `codeTemplate` is
 * what the list prints.
 *
 * BOARDS PRICE BY THE LINEAL METRE, THE TWO PARQUETRY RANGES PRICE BY THE m2.
 * `unit` says which per row. The $/LM and $/m2 columns agree on every board row
 * that prints both, so the m2 figure is a cross-check and not a second rate.
 *
 * THIS LIST PRINTS FREIGHT WHERE THE OTHER TWO HURFORD'S LISTS DO NOT: $80 the first
 * pack then $15 a pack, or $320/$450 for a crane truck to site. Damien has settled
 * what Terra pays: $0 into the warehouse, since Terra unload with their own
 * forklift, and a flat $320 straight to site. Both the printed figures and the
 * Terra-facing ones are exported below for the seed to turn into fee rules.
 */

export const HURFORDS_SOLID_EFFECTIVE_DATE = "2026-02-12";
export const HURFORDS_SOLID_SOURCE = "Hurford's QLD Solid Flooring Products Price List, effective 12 February 2026";

/** $80 + GST once, for an order carrying less than full pack quantities. */
export const HURFORDS_SOLID_JOB_LOT_FEE_EX_GST = 80;
/** Yard or depot freight: $80 + GST the first pack, then $15 + GST each pack after it. */
export const HURFORDS_SOLID_FREIGHT_FIRST_PACK_EX_GST = 80;
export const HURFORDS_SOLID_FREIGHT_EXTRA_PACK_EX_GST = 15;
/** Crane truck to site, instead of the per-pack yard freight above. */
export const HURFORDS_SOLID_CRANE_BNE_GC_EX_GST = 320;
export const HURFORDS_SOLID_CRANE_SUNSHINE_EX_GST = 450;
/**
 * Boxed parquetry is charged differently, and the sheet prints THREE figures for it:
 * a $150 broken pack fee, a $150 freight fee, and a note that the $80 freight
 * surcharge also applies. Whether the $80 stacks on the $150 is not stated.
 */
export const HURFORDS_SOLID_PARQUETRY_BROKEN_PACK_FEE_EX_GST = 150;
export const HURFORDS_SOLID_PARQUETRY_FREIGHT_FEE_EX_GST = 150;
export const HURFORDS_SOLID_PARQUETRY_FREIGHT_SURCHARGE_EX_GST = 80;
/**
 * TERRA'S OWN RULE, NOT HURFORD'S. Up to this many m2 defaults to Terra collecting
 * to the shop at $0 Hurford freight; over it defaults to the crane truck to site.
 * The sheet says so itself and says it is overridable, and that it applies to
 * Hurford SOLID flooring only.
 */
export const HURFORDS_SOLID_TERRA_PICKUP_M2_THRESHOLD = 10;

/**
 * DELIVERY INTO TERRA'S WAREHOUSE IS FREE, AND IT OVERRIDES EVERY PRINTED FREIGHT
 * FIGURE ABOVE. Damien: Terra unload with their own forklift, so no crane truck and
 * no tailgate is needed and Hurford's charge nothing to bring solid timber in. The
 * per-pack and crane figures stay recorded for reference and for a site delivery,
 * but a warehouse order carries no freight at all.
 */
export const HURFORDS_SOLID_WAREHOUSE_FREIGHT_EX_GST = 0;
/**
 * A delivery straight to site is a FLAT $320 + GST with the crane truck, whatever
 * the load, per Damien. The Sunshine Coast rate is printed by Hurford's but is not
 * relevant to Terra, so it is never auto-applied.
 */
export const HURFORDS_SOLID_SITE_FREIGHT_FLAT_EX_GST = 320;
export const HURFORDS_SOLID_SUNSHINE_RATE_RELEVANT = false;
/**
 * On boxed parquetry into the warehouse only the $150 BROKEN PACK fee lands. Damien:
 * "$150 broken pack, to my warehouse it's free". The $150 freight fee and the $80
 * freight surcharge printed beside it are freight, and freight in is free.
 */
export const HURFORDS_SOLID_PARQUETRY_WAREHOUSE_FEE_EX_GST = 150;
/**
 * The 109 rows with no pack size are random-length natural timber, per Damien, and
 * run these lengths. There is no pack quantity to publish, so they quote by the
 * lineal metre.
 */
export const HURFORDS_SOLID_RANDOM_LENGTH_MIN_M = 1;
export const HURFORDS_SOLID_RANDOM_LENGTH_MAX_M = 6;

export type HurfordsSolidRow = {
  /** Orderable code, with the row's grade code substituted into the template slot. */
  code: string;
  /** As the list prints it, '##' or '#' and all. Kept for matching an invoice. */
  codeTemplate: string;
  /** 2 on most rows, 1 on the 9 mistyped ones, 0 where the code is already complete. */
  codeHashes: number;
  range: string;
  /** The name for the price book, with the one source misspelling corrected. */
  species: string;
  /** Exactly as printed, so an invoice can be matched either way. */
  speciesPrinted: string;
  speciesMisspeltInSource: boolean;
  /** The 2 XL rows that print the board size inside the species text. Stripped out of `species`. */
  speciesSizeInPrintedName: boolean;
  /** As printed, e.g. 'Select (SL)'. */
  grade: string;
  gradeCode: string;
  /** Secret Nail / Top Nail / Micro T&G / Block Parquetry — part of the identity. */
  profile: string;
  printedCategory: string;
  category: string;
  form: "board" | "parquetry";
  /** "lm" on a board, "m2" on parquetry. The list genuinely prices them differently. */
  unit: "lm" | "m2";
  sizePrinted: string;
  widthMm: number;
  thicknessMm: number;
  /** Parquetry only. A solid board is random length, so it has none. */
  lengthMm: number | null;
  /** true on the 2 XL rows whose size column prints 650 where the board is 640. */
  sizeColumnLengthWrong: boolean;
  /** The rate on a board row. null on parquetry, which prints no $/LM. */
  pricePerLm: number | null;
  /** The rate on a parquetry row, and the printed cross-check on a board row. */
  pricePerM2: number | null;
  /** $/LM over the board width. Within 0.5% of pricePerM2 on every board row. */
  pricePerM2Derived: number | null;
  lmAndM2Agree: boolean | null;
  /** Row 491 only: Cypress Pine 62 x 20 prints no rate at all. */
  priceOnApplication: boolean;
  /** Lineal metres in a full pack. null on parquetry and on the 109 rows that print none. */
  packLm: number | null;
  packLmPrinted: string | null;
  /** Random-length board with no pack quantity published. Quote by the lineal metre. */
  randomLengthNoPack: boolean;
  /** Parquetry: boards or blocks in a box. */
  piecesPerBox: number | null;
  pieceM2: number | null;
  boxM2Printed: number | null;
  boxM2Derived: number | null;
  /** Block Hardwood Parquetry prints a box price. It reconciles to the rate exactly. */
  boxPricePrinted: number | null;
  boxPriceDerived: number | null;
  /** 'Random length', '0.6m to 4.5m - End Matched', or the parquetry box wording. */
  lengthNotes: string;
  /** Every grade offered on this same board, dearest first. The big price lever. */
  gradesOnThisBoard: string;
  gradeCountOnThisBoard: number;
  sourceRow: number;
  sourcePage: number | null;
  variantKey: string;
};

